window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6dd7e55e407f4490"]={"versions": [{"id": "FIG-6dd7e55e407f4490", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Ablaufdiagramm zur Konfiguration und zeitlichen Steuerung des Watchdog Managers (Wdm / WdgM) in der AUTOSAR Classic Platform. Das Diagramm illustriert Schritt 3 der Konfigurationsableitung („3.step : derive prescaler-parameters of Watchdog Manager for triggering Watchdog Instances“) und stellt das zyklische Triggern mehrerer Watchdog-Instanzen über Prescaler auf einer gemeinsamen Zeitachse dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Watchdog Manager (Wdm / WdgM)</strong>: Übergeordnete BSW-Komponente zur Überwachung und Triggerung der Watchdogs.</li>\n<li><strong>Watchdog Instance 1</strong>: Erste logische oder physische Watchdog-Treibereinheit mit eigenem Triggerzyklus.</li>\n<li><strong>Watchdog Instance 2</strong>: Zweite Watchdog-Treibereinheit mit abweichendem Triggerzyklus.</li>\n<li><strong>Prescaler / Referenzzyklen</strong>: Konfigurationsparameter <code>trigger reference cycle (of instance 1) = 3</code> und <code>trigger reference cycle (of instance 2) = 4</code>.</li>\n<li><strong>Zeitachse ($t$)</strong>: Diskrete Zeitachse basierend auf der grundlegenden Aufrufperiode des Watchdog Managers bzw. dessen MainFunction.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm zeigt zwei parallele Zeitstrahlen $t$ für „Watchdog Instance 1“ und „Watchdog Instance 2“.</li>\n<li>Jede gestrichelte vertikale Hilfslinie repräsentiert einen Basis-Ausführungszyklus der zyklischen Hauptfunktion des Watchdog Managers (Ticks 1, 2, 3, ...).</li>\n<li>Für <strong>Watchdog Instance 1</strong> erfolgt die Triggerung (blau hervorgehobener, durchgezogener vertikaler Strich) periodisch nach jedem 3. Basiszyklus (<code>trigger reference cycle = 3</code>, d. h. bei Tick 3, 6, 9, 12).</li>\n<li>Für <strong>Watchdog Instance 2</strong> erfolgt die Triggerung (rot hervorgehobener, durchgezogener vertikaler Strich) periodisch nach jedem 4. Basiszyklus (<code>trigger reference cycle = 4</code>, d. h. bei Tick 4, 8, 12).</li>\n<li>Bei Zyklus 12 fallen die Triggerzeitpunkte beider Instanzen zusammen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Konfigurationsparameter für die Watchdog-Triggerung müssen als ganzzahlige Vielfache (Prescaler / Reference Cycles) der Periodizität der <code>WdgM_MainFunction</code> gewählt werden.</li>\n<li>Jede Watchdog-Instanz besitzt unabhängige Timeout- und Triggeranforderungen der zugrunde liegenden Watchdog-Hardware bzw. des Watchdog-Treibers (Wdg), die durch die jeweiligen Prescaler-Werte bedient werden.</li>\n<li>Integratoren müssen sicherstellen, dass die Basiszykluszeit des Watchdog Managers als gemeinsamer Teiler für die geforderten Triggerintervalle aller angebundenen Watchdog-Instanzen ausgelegt ist.</li>\n</ul>"}, {"id": "FIG-10592f7f15e0b49c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Ablaufdiagramm zur Konfiguration und zeitlichen Steuerung des Watchdog Managers (Wdm / WdgM) in der AUTOSAR Classic Platform. Das Diagramm illustriert Schritt 3 der Konfigurationsableitung („3.step : derive prescaler-parameters of Watchdog Manager for triggering Watchdog Instances“) und stellt das zyklische Triggern mehrerer Watchdog-Instanzen über Prescaler auf einer gemeinsamen Zeitachse dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Watchdog Manager (Wdm / WdgM)</strong>: Übergeordnete BSW-Komponente zur Überwachung und Triggerung der Watchdogs.</li>\n<li><strong>Watchdog Instance 1</strong>: Erste logische oder physische Watchdog-Treibereinheit mit eigenem Triggerzyklus.</li>\n<li><strong>Watchdog Instance 2</strong>: Zweite Watchdog-Treibereinheit mit abweichendem Triggerzyklus.</li>\n<li><strong>Prescaler / Referenzzyklen</strong>: Konfigurationsparameter <code>trigger reference cycle (of instance 1) = 3</code> und <code>trigger reference cycle (of instance 2) = 4</code>.</li>\n<li><strong>Zeitachse ($t$)</strong>: Diskrete Zeitachse basierend auf der grundlegenden Aufrufperiode des Watchdog Managers bzw. dessen MainFunction.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Das Diagramm zeigt zwei parallele Zeitstrahlen $t$ für „Watchdog Instance 1“ und „Watchdog Instance 2“.</li>\n<li>Jede gestrichelte vertikale Hilfslinie repräsentiert einen Basis-Ausführungszyklus der zyklischen Hauptfunktion des Watchdog Managers (Ticks 1, 2, 3, ...).</li>\n<li>Für <strong>Watchdog Instance 1</strong> erfolgt die Triggerung (blau hervorgehobener, durchgezogener vertikaler Strich) periodisch nach jedem 3. Basiszyklus (<code>trigger reference cycle = 3</code>, d. h. bei Tick 3, 6, 9, 12).</li>\n<li>Für <strong>Watchdog Instance 2</strong> erfolgt die Triggerung (rot hervorgehobener, durchgezogener vertikaler Strich) periodisch nach jedem 4. Basiszyklus (<code>trigger reference cycle = 4</code>, d. h. bei Tick 4, 8, 12).</li>\n<li>Bei Zyklus 12 fallen die Triggerzeitpunkte beider Instanzen zusammen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Konfigurationsparameter für die Watchdog-Triggerung müssen als ganzzahlige Vielfache (Prescaler / Reference Cycles) der Periodizität der <code>WdgM_MainFunction</code> gewählt werden.</li>\n<li>Jede Watchdog-Instanz besitzt unabhängige Timeout- und Triggeranforderungen der zugrunde liegenden Watchdog-Hardware bzw. des Watchdog-Treibers (Wdg), die durch die jeweiligen Prescaler-Werte bedient werden.</li>\n<li>Integratoren müssen sicherstellen, dass die Basiszykluszeit des Watchdog Managers als gemeinsamer Teiler für die geforderten Triggerintervalle aller angebundenen Watchdog-Instanzen ausgelegt ist.</li>\n</ul>"}], "trans": [{"from": "FIG-6dd7e55e407f4490", "to": "FIG-10592f7f15e0b49c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
